 {label:'Functional status',fields:[{key:'mobility',label:'Current mobility and assistive devices',type:'textarea',required:true},{key:'daily_activities',label:'Activities that are difficult today',type:'textarea',required:true},{key:'caregiver_support',label:'Caregiver or support needs',type:'textarea',required:false}]},
 {label:'Consent and visit preparation',fields:[{key:'privacy_acknowledged',label:'I acknowledge the practice privacy notice',type:'checkbox',required:true},{key:'treatment_consent',label:'I consent to evaluation and treatment during this visit',type:'checkbox',required:true}]}
