 return `<p class="eyebrow">REVIEWED CHART HANDOFF</p><div class="section-head"><h2>${esc(item.patient_name)}</h2><button type="button" data-intake-open="${esc(item.packet_id)}">Back to packet</button></div>${intakeBindingView(item)}<p>Choose exact patient answers to add to contact demographics. Unselected fields remain unchanged. Medical history, medication and allergy answers remain review evidence; this action does not create diagnoses, prescriptions or signed notes.</p><details><summary>All submitted answers</summary>${intakeAnswersView(item)}</details>${fields.length?`<form id="workflow-intake-demographics" data-packet="${esc(item.packet_id)}" data-version="${item.packet_version}" data-demographics-version="${demographics.version}">${fields.map(field=>{const key=field.chart_target.slice(13),answer=item.response?.[field.key],current=demographics.content?.[key],available=typeof answer==='string'&&answer.trim();return `<fieldset class="reconciliation-field"><legend>${esc(field.label)} → ${esc(human(key))}</legend><p>Current chart: <strong>${esc(current||'Not recorded')}</strong></p><p>Patient answer: <strong>${esc(answer??'Not answered')}</strong></p>${current&&available&&current!==answer?'<p class="notice error">This differs from the chart. Applying it creates an attributed revision.</p>':''}<label class="review-ack"><input type="checkbox" name="field" value="${esc(field.key)}" ${available?'':'disabled'}> Apply this exact answer</label></fieldset>`;}).join('')}<label>Reason<input name="reason" required maxlength="800" value="Reviewed patient-submitted contact details"></label><label class="review-ack"><input name="reviewed" type="checkbox" required> I reviewed the selected answers and any chart differences.</label><button type="submit">Apply selected mapped answers</button></form>`:'<p class="notice">This form has no chart mappings. The answers remain available as reviewed evidence.</p>'}`;
