const intakeChartValue=(content,target)=>String(target.split('.').reduce((value,key)=>value?.[key],content)??'').trim();
const intakeSame=(target,answer,current)=>target==='administrative_gender'||target.startsWith('identity.')&&target!=='identity.birth_date'?answer.toLowerCase()===current.toLowerCase():answer===current;
// One answer next to what the chart holds now. A box is offered only for
