function installPrevisitNavigation(){const schedule=document.getElementById('nav-schedule');if(!schedule||document.getElementById('nav-previsit'))return;const button=document.createElement('button');button.id='nav-previsit';button.className='nav-item';button.type='button';button.innerHTML='<span aria-hidden="true">✓</span><span>Pre-visit readiness</span>';schedule.after(button);}
function previsitReadinessView(items,template){
 const canIssue=['owner','clinician','front_desk'].includes(me?.role);
 const actions=item=>{if(item.status==='not_issued'){if(item.workflow_instance_id)return `<button type="button" data-journey-open-run="${esc(item.workflow_instance_id)}">Issue workflow forms in journey</button>`;return canIssue?`<button type="button" data-previsit-issue="${esc(item.appointment_id)}">Issue default forms</button>`:'<span class="muted">Front desk, a clinician or the owner can send the intake form.</span>';}if(item.status==='submitted'&&canIssue)return `<button type="button" data-previsit-review="${esc(item.packet_id)}" data-version="${item.packet_version}">Review answers</button>`;if(item.status==='reviewed'&&canIssue)return `<button type="button" data-previsit-reconcile="${esc(item.packet_id)}">Review chart handoff</button>`;return item.packet_id?`<button type="button" data-intake-open="${esc(item.packet_id)}">Open packet</button>`:'';};
 return `<section class="billing-section" aria-labelledby="previsit-readiness-heading"><h3 id="previsit-readiness-heading">Upcoming readiness</h3><p class="muted">Workflow forms are issued from their patient journey. “Issue default forms” sends the practice’s intake form${template?'':' (the standard form until the owner saves their own)'}.</p>${items.length?`<div class="billing-table-wrap"><table class="billing-table"><thead><tr><th>Patient</th><th>Appointment</th><th>Forms</th><th>Attestation</th><th>Next action</th></tr></thead><tbody>${items.map(item=>`<tr><td>${esc(item.patient_name)}<small>MRN ${esc(item.mrn)}</small></td><td>${esc(date(item.starts_at))}</td><td><span class="pill">${esc(human(item.status))}</span>${item.workflow_step_key?`<small>${esc(item.workflow_step_key)} · workflow v${item.workflow_definition_version}</small>`:'<small>Default intake</small>'}</td><td>${esc(item.attested_name||'Awaiting submission')}</td><td>${actions(item)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice"><b>No upcoming appointments in this readiness window</b><p>Book an appointment to prepare default intake, or open a patient journey to issue and review its saved workflow forms.</p><button type="button" data-journey-workqueue>Open patient journeys</button></div>'}</section>`;
}
function previsitAvailabilityFields(profile){return `<div class="form-grid availability-fields"><label>Timezone<input name="booking_timezone" required maxlength="100" value="${esc(profile?.booking_timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC')}"></label><label>Weekdays<input name="available_weekdays" required placeholder="1,2,3,4,5" value="${esc((profile?.available_weekdays||[1,2,3,4,5]).join(','))}"></label><label>Day starts<input name="day_start" type="time" required value="${esc((profile?.day_start||'08:00').slice(0,5))}"></label><label>Day ends<input name="day_end" type="time" required value="${esc((profile?.day_end||'17:00').slice(0,5))}"></label><label>Slot interval (minutes)<input name="slot_minutes" type="number" min="5" max="240" required value="${profile?.slot_minutes||30}"></label></div>`;}
async function showPrevisit(){previsitChartReturn=null;const [settings,data,providers]=await Promise.all([api('/api/v1/previsit/settings'),api('/api/v1/previsit/readiness'),api('/api/v1/schedule/providers')]);previsitReadinessItems=data.items;previsitReconciliation=null;previsitStandard=settings.standard||null;showTool('Pre-visit readiness');const profile=settings.profile,template=settings.template,canOwn=me?.role==='owner',intakeMode=settings.intake_mode||(template&&template.schema?.base!=='standard'?'own':'standard');
 const publicUrl=profile?`${location.origin}/book/${encodeURIComponent(profile.public_slug)}`:'';
 const configuration=canOwn?`<details id="previsit-configuration" class="billing-section"><summary><strong>Booking and intake settings</strong></summary><p class="muted">Set up public booking and the intake form patients fill in. Patient journey forms use the questions saved in their own journey. A form that was already sent keeps the questions it was sent with.</p><section class="billing-section"><div class="section-head"><div><h3>Public booking</h3><p>${profile?.enabled?'Enabled':'Not enabled'}${publicUrl?` · <a href="${esc(publicUrl)}" target="_blank" rel="noopener">Open booking page ↗</a>`:''}</p></div></div>${canOwn?`<form id="previsit-settings-form" data-version="${profile?.version||0}"><div class="form-grid"><label>Public link name<input name="public_slug" required pattern="[a-z0-9][a-z0-9-]{2,62}" value="${esc(profile?.public_slug||'new-patients')}"></label><label>Default clinician<select name="default_clinician_id" required>${providers.items.map(provider=>`<option value="${esc(provider.id)}" ${provider.id===(profile?.default_clinician_id||me.user_id)?'selected':''}>${esc(provider.label)}</option>`).join('')}</select></label><label>Appointment title<input name="appointment_title" required value="${esc(profile?.appointment_title||'New patient visit')}"></label><label>Category<input name="appointment_category" required value="${esc(profile?.appointment_category||'New patient')}"></label><label>Duration (minutes)<input name="duration_minutes" type="number" min="5" max="480" value="${profile?.duration_minutes||60}" required></label><label>Booking horizon (days)<input name="booking_horizon_days" type="number" min="1" max="365" value="${profile?.booking_horizon_days||180}" required></label></div>${previsitAvailabilityFields(profile)}<label>Welcome text<textarea name="welcome_text" maxlength="1000">${esc(profile?.welcome_text||'Request an appointment with our practice. We will review your information before the visit.')}</textarea></label><label class="review-ack"><input name="enabled" type="checkbox" ${profile?.enabled?'checked':''}>Allow public appointment requests</label><label>Change reason<input name="reason" required value="Configure patient-directed booking"></label><button type="submit" ${providers.items.length?'':'disabled'}>Save booking settings</button></form>${providers.items.length?'':'<p class="notice error">Add an active owner or clinician before enabling public booking.</p>'}`:'<p class="muted">A practice owner manages the public booking link.</p>'}</section>
 <section class="billing-section"><div class="section-head"><div><h3>Intake form</h3><p>${template?`${esc(template.name)} · saved ${Number(template.version)} time${Number(template.version)===1?'':'s'}`:'Standard intake form · nothing saved yet'}</p></div></div>${canOwn?`<form id="previsit-template-form" data-id="${esc(template?.id||'')}" data-version="${template?.version||0}"><label>Form name<input name="name" required maxlength="200" value="${esc(template?.name||'New patient intake')}"></label>${intakeTemplateBuilder(template?.schema||null,intakeMode,settings.standard||null)}<input type="hidden" name="active" value="true"><label>Change reason<input name="reason" required value="Update the intake form"></label><button type="submit" class="primary">Save intake form</button></form>`:'<p class="muted">A practice owner manages intake forms.</p>'}</section></details>`:'';
 $('tools').innerHTML=`<p class="eyebrow">PATIENT ACCESS</p><div class="section-head"><div><h2>Pre-visit readiness</h2><p>Review upcoming patient forms and continue their chart handoff.</p></div><button type="button" data-previsit-refresh>Refresh</button></div>${issuedPrevisitLink?`<section class="notice"><strong>Intake form link ready</strong><p>This link is shown only now. Copy it and send it to the patient the way your practice normally contacts them.</p><div class="actions"><input id="issued-previsit-link" readonly value="${esc(issuedPrevisitLink)}"><button type="button" data-previsit-copy>Copy link</button></div></section>`:''}
 ${previsitReadinessView(data.items,template)}${configuration}`;
}
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-intake-add-section],[data-intake-remove-section],[data-intake-move-section],[data-intake-add-field],[data-intake-remove-field],[data-intake-move-field]');if(!button)return;const form=button.closest('#previsit-template-form');if(!form)return;event.preventDefault();event.stopImmediatePropagation();const section=button.closest('[data-intake-section]'),field=button.closest('[data-intake-field]');if(button.hasAttribute('data-intake-add-section')){form.querySelector('[data-intake-sections]').insertAdjacentHTML('beforeend',intakeSectionEditor({},form.querySelectorAll('[data-intake-section]').length));return;}if(button.hasAttribute('data-intake-remove-section')){if(form.querySelectorAll('[data-intake-section]').length===1&&form.querySelector('input[name="intake_mode"]:checked')?.value!=='standard'){notice('Your own form needs at least one section.',true);return;}section.remove();return;}if(button.dataset.intakeMoveSection){const sibling=button.dataset.intakeMoveSection==='up'?section.previousElementSibling:section.nextElementSibling;if(sibling)(button.dataset.intakeMoveSection==='up'?sibling.before(section):sibling.after(section));return;}if(button.hasAttribute('data-intake-add-field')){const host=section.querySelector('[data-intake-fields]');host.insertAdjacentHTML('beforeend',intakeFieldEditor({},[...form.querySelectorAll('[data-intake-section]')].indexOf(section),host.querySelectorAll('[data-intake-field]').length));return;}if(button.hasAttribute('data-intake-remove-field')){field.remove();return;}const sibling=button.dataset.intakeMoveField==='up'?field.previousElementSibling:field.nextElementSibling;if(sibling)(button.dataset.intakeMoveField==='up'?sibling.before(field):sibling.after(field));},true);
document.addEventListener('change',event=>{const type=event.target.closest?.('[data-intake-field-type]');if(!type)return;type.closest('[data-intake-field]').querySelector('[data-intake-options-wrap]').hidden=type.value!=='select';},true);
