document.addEventListener('change',event=>{const choice=event.target.closest?.('input[name="intake_mode"]');const form=choice?.closest('#previsit-template-form');if(!form)return;const standard=choice.value==='standard',copy=intakeModeCopy[standard?'standard':'own'];for(const node of form.querySelectorAll('[data-intake-standard-only]'))node.hidden=!standard;form.querySelector('[data-intake-own-title]').textContent=copy[0];form.querySelector('[data-intake-own-hint]').textContent=copy[1];const host=form.querySelector('[data-intake-sections]');if(!standard&&!host.querySelector('[data-intake-section]'))host.innerHTML=defaultIntakeTemplate.sections.map(intakeSectionEditor).join('');},true);
document.addEventListener('submit',event=>{const form=event.target;if(form.id!=='previsit-template-form')return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{const data=Object.fromEntries(new FormData(form));data.id=form.dataset.id||null;data.active=true;delete data.intake_mode;data.schema=intakeTemplateSchema(form);await api('/api/v1/previsit/templates','POST',data,Number(form.dataset.version));notice('Intake form saved. Forms already sent keep their questions.');await showPrevisit();});},true);
document.addEventListener('click',event=>{const button=event.target.closest?.('#nav-previsit,[data-previsit-refresh],[data-previsit-issue],[data-previsit-copy],[data-previsit-reconcile],[data-previsit-back]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{if(button.dataset.previsitCopy!==undefined){await navigator.clipboard.writeText(issuedPrevisitLink);notice('Intake form link copied.');return;}if(button.hasAttribute('data-previsit-back')){if(await returnToPatientIntakeChart())return;await showPrevisit();return;}if(button.dataset.previsitReconcile){await openPrevisitReconciliation(button.dataset.previsitReconcile);return;}if(button.dataset.previsitIssue){const saved=await api(`/api/v1/appointments/${button.dataset.previsitIssue}/intake-packet`,'POST',{});issuedPrevisitLink=`${location.origin}${saved.intake_url}`;notice('The intake form link is ready. Copy it now; it is not shown again.');}if(button.dataset.previsitReview){await api(`/api/v1/previsit/packets/${button.dataset.previsitReview}/review`,'POST',{},Number(button.dataset.version));notice('Patient-submitted intake marked reviewed.');}await showPrevisit();});},true);
document.addEventListener('submit',event=>{const form=event.target;if(!['previsit-settings-form','previsit-template-form','intake-demographics-reconcile','intake-coverage-reconcile','intake-functional-reconcile'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{const data=Object.fromEntries(new FormData(form));if(form.id==='previsit-settings-form'){data.enabled=form.elements.enabled.checked;data.default_clinician_id=data.default_clinician_id.trim();data.duration_minutes=Number(data.duration_minutes);data.booking_horizon_days=Number(data.booking_horizon_days);data.available_weekdays=data.available_weekdays.split(',').map(value=>Number(value.trim())).filter(Number.isInteger);data.day_start=`${data.day_start}:00`;data.day_end=`${data.day_end}:00`;data.slot_minutes=Number(data.slot_minutes);await api('/api/v1/previsit/settings','PUT',data,Number(form.dataset.version));notice('Public booking settings saved.');await showPrevisit();return;}if(form.id==='previsit-template-form'){data.id=data.id||null;data.active=true;try{data.schema=JSON.parse(data.schema);}catch{throw new Error('The intake template definition is not valid JSON.');}await api('/api/v1/previsit/templates','POST',data,Number(form.dataset.version));notice('Intake template saved.');await showPrevisit();return;}const state=previsitReconciliation;if(!state||state.item.packet_id!==form.dataset.packet)throw new Error('Reload the reviewed intake before saving.');if(form.id==='intake-demographics-reconcile'){const content=structuredClone(state.demographics.content||{});let selectedFields=0;for(const key of ['preferred_name','pronouns','administrative_gender'])if(form.elements[`apply_${key}`].checked){content[key]=data[key]||null;selectedFields++;}if(form.elements.apply_address.checked){content.address={line1:data.address_line1||null,line2:data.address_line2||null,city:data.address_city||null,region:data.address_region||null,postal_code:data.address_postal_code||null,country:data.address_country?data.address_country.toUpperCase():null};selectedFields++;}if(!selectedFields)throw new Error('Select at least one demographic field to apply.');await api(`/api/v1/patients/${form.dataset.patient}/demographics`,'PUT',{content,reason:`Intake packet ${form.dataset.packet}: ${data.reason}`},Number(form.dataset.version));notice('Selected demographic fields promoted with attributed history.');}
 else if(form.id==='intake-coverage-reconcile'){const centsValue=String(data.copay||'').trim();const copay_cents=centsValue===''?null:Math.round(Number(centsValue)*100);if(copay_cents!=null&&(!Number.isInteger(copay_cents)||copay_cents<0))throw new Error('Enter a valid nonnegative copay.');await api(`/api/v1/patients/${form.dataset.patient}/coverages`,'POST',{request_id:form.dataset.request,source_history_id:null,content:{payer_id:data.payer_id,priority:data.priority,status:'active',member_id:data.member_id,group_number:data.group_number,plan_name:data.plan_name,subscriber_name:data.subscriber_name,subscriber_birth_date:data.subscriber_birth_date||null,relationship:data.relationship,effective_date:data.effective_date,end_date:data.end_date||null,copay_cents,verification:data.verification,notes:data.notes},reason:`Intake packet ${form.dataset.packet}: ${data.reason}`});notice('A separate native coverage record was created with attribution.');}
 else{await api(`/api/v1/patients/${form.dataset.patient}/functional-status`,'POST',{request_id:form.dataset.request,visit_id:null,supersedes_id:data.supersedes_id||null,content:{mobility:data.mobility,transfers:data.transfers,self_care:data.self_care,communication:data.communication,falls_last_90_days:Number(data.falls_last_90_days),assistive_devices:data.assistive_devices.split(',').map(v=>v.trim()).filter(Boolean),patient_goal:data.patient_goal,scale_name:data.scale_name,scale_score:data.scale_score,notes:data.notes},reason:`Intake packet ${form.dataset.packet}: ${data.reason}`});notice('A new attributed functional-status assessment was created.');}await openPrevisitReconciliation(form.dataset.packet);});},true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',installPrevisitNavigation,{once:true});else installPrevisitNavigation();

document.addEventListener('click',event=>{const button=event.target.closest?.('[data-previsit-review],[data-intake-open]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();run(()=>openWorkflowIntakePacket(button.dataset.previsitReview||button.dataset.intakeOpen));},true);
document.addEventListener('submit',event=>{const form=event.target;if(!['workflow-intake-review','workflow-intake-demographics'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{if(!form.elements.reviewed.checked)throw new Error('Review the displayed answers before continuing.');const account=previsitAccount(),packet=form.dataset.packet,button=form.querySelector('button[type="submit"]');button.disabled=true;try{if(form.id==='workflow-intake-review'){await api(`/api/v1/previsit/packets/${packet}/review`,'POST',{},Number(form.dataset.version));if(account!==previsitAccount()||!form.isConnected)return;notice('This intake version was reviewed. No chart fields were changed.');await openWorkflowIntakePacket(packet);}else{const fields=Array.from(form.querySelectorAll('input[name="field"]:checked')).map(input=>input.value);if(!fields.length)throw new Error('Select at least one mapped answer.');await api(`/api/v1/previsit/packets/${packet}/demographics`,'POST',{fields,demographics_version:Number(form.dataset.demographicsVersion),reason:form.elements.reason.value},Number(form.dataset.version));if(account!==previsitAccount()||!form.isConnected)return;notice('Selected answers added to demographics with packet provenance.');await openPrevisitReconciliation(packet);}}finally{if(form.isConnected)button.disabled=false;}});},true);

document.addEventListener('submit',event=>{const form=event.target;if(!['intake-standard-review','intake-standard-coverage'].includes(form?.id))return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{
 const state=previsitStandardReview,packet=form.dataset.packet,account=previsitAccount();if(!state||state.item.packet_id!==packet)throw new Error('Reload this intake form before saving.');
 const button=form.querySelector('button[type="submit"]');button.disabled=true;
 try{
  if(form.id==='intake-standard-coverage'){
   const data=Object.fromEntries(new FormData(form));
   await api(`/api/v1/patients/${form.dataset.patient}/coverages`,'POST',{request_id:form.dataset.request,source_history_id:null,content:{payer_id:data.payer_id,priority:data.priority,status:'active',member_id:data.member_id,group_number:data.group_number,plan_name:data.plan_name,subscriber_name:data.subscriber_name,subscriber_birth_date:data.subscriber_birth_date||null,relationship:data.relationship,effective_date:data.effective_date,end_date:null,copay_cents:null,verification:'unverified',notes:'From the patient’s intake form.'},reason:`Intake form ${packet}: ${data.reason}`});
   if(account!==previsitAccount())return;notice(`Saved as ${data.priority} insurance. Check eligibility before the visit.`);
  }else{
   const fields=Array.from(form.elements).filter(input=>input.name==='field'&&input.checked).map(input=>input.value),reviewed=form.dataset.status==='reviewed';
   if(reviewed&&!fields.length)throw new Error('Tick at least one answer to add to the chart.');
   let version=Number(form.dataset.version);
   if(!reviewed){const saved=await api(`/api/v1/previsit/packets/${packet}/review`,'POST',{},version);version=Number(saved.version);}
   if(fields.length)await api(`/api/v1/previsit/packets/${packet}/demographics`,'POST',{fields,demographics_version:Number(form.dataset.demographicsVersion),reason:form.elements.reason.value},version);
   if(account!==previsitAccount())return;notice(fields.length?`Reviewed. ${fields.length} answer${fields.length===1?' was':'s were'} added to the chart.`:'Marked reviewed. The chart was not changed.');
  }
  await openWorkflowIntakePacket(packet);
 }finally{if(form.isConnected)button.disabled=false;}
});},true);
// Narrow a long list of insurance companies while choosing one in the review.
document.addEventListener('input',event=>{const box=event.target.closest?.('[data-intake-payer-filter]');if(!box)return;const select=box.closest('form')?.elements?.payer_id;if(!select)return;const text=box.value.trim().toLowerCase();for(const option of select.options){if(option.value)option.hidden=!!text&&!option.textContent.toLowerCase().includes(text);}if(select.selectedOptions[0]?.hidden)select.value=[...select.options].find(option=>option.value&&!option.hidden)?.value||'';},true);
// Add a missing insurance company without leaving the review; the coverage form stays as it was.
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-intake-add-payer]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();run(async()=>{
 const box=button.closest('[data-intake-add-payer-box]'),form=button.closest('form'),name=box.querySelector('[data-intake-payer-name]').value.trim(),code=box.querySelector('[data-intake-payer-code]').value.trim();
 if(!name)throw new Error('Enter the insurance company’s name.');
 button.disabled=true;
 try{
  const saved=await api('/api/v1/billing/payers','POST',{request_id:crypto.randomUUID(),source_history_id:null,content:{name,payer_code:code,phone:'',address:'',active:true},reason:'Added while reviewing a patient intake form'});
  if(!form.isConnected)return;
  const select=form.elements.payer_id;select.insertAdjacentHTML('beforeend',`<option value="${esc(saved.id)}">${esc(saved.content?.name||name)}</option>`);select.value=saved.id;box.hidden=true;
  notice(`${saved.content?.name||name} was added and is selected. Finish the details and save.`);
 }finally{button.disabled=false;}
});},true);
